<?php $vals=[]; foreach($settings as $s) $vals[$s['key']]=$s['value']; $defaults=['scan_roots'=>implode(',',config('guard.scan_roots')),'quarantine_path'=>config('guard.quarantine_path'),'scan_interval_minutes'=>config('guard.scan_interval_minutes'),'web_actions_enabled'=>config('guard.web_actions_enabled')?'true':'false','openai_api_key'=>config('guard.openai_api_key'),'openai_enabled'=>config('guard.openai_enabled')?'true':'false','max_file_read_bytes'=>config('guard.max_file_read_bytes')]; ob_start(); ?><h1>Settings</h1><p class="muted">Settings are stored in SQLite for the MVP. Environment variables remain authoritative for runtime config until you wire them into deployment.</p><form method="post" class="card"><?php foreach($defaults as $k=>$v): ?><label><?= e($k) ?><br><input class="input" style="width:100%" name="settings[<?= e($k) ?>]" value="<?= e($vals[$k] ?? $v) ?>"></label><br><br><?php endforeach ?><button class="btn">Save</button></form><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
